{"path": "tax.py", "content": "from decimal import Decimal, ROUND_HALF_UP

CENT = Decimal("0.01")


def to_decimal(value):
    # Go through str so binary float artifacts (e.g. 1.25 * 0.1 == 0.12499...) don't skew rounding.
    return value if isinstance(value, Decimal) else Decimal(str(value))


def line_tax_exact(price, rate):
    """Tax for one line, rounded half-up to whole cents, as a Decimal."""
    return (to_decimal(price) * to_decimal(rate)).quantize(CENT, rounding=ROUND_HALF_UP)


def line_tax(price, rate):
    return float(line_tax_exact(price, rate))
