{"path": "cart.py", "content": "from tax import CENT, line_tax_exact, to_decimal


def total_with_tax(prices, rate):
    # Each line's tax is rounded to cents before summing; sum in Decimal to avoid float drift.
    total = sum((to_decimal(p) + line_tax_exact(p, rate) for p in prices), Decimal(0))
    return float(total.quantize(CENT))
